### corpus/src/services/pricingService.js
   1 const { roundMoney } = require("../lib/currency");
   2 
   3 /**
   4  * Volume pricing. Tiers arrive sorted ascending by minQuantity.
   5  */
   6 class PricingService {
   7     constructor(repo, clock) {
   8         this.repo = repo;
   9         this.clock = clock;
  10     }
  11 
  12     async quote(orderId, options = {}) {
  13         const order = await this.repo.loadBatch(orderId);
  14         const tiers = await this.repo.findCoupons(orderId);
  15         let total = 0;
  16 
  17         for (const line of order.lines) {
  18             total += this.priceLine(line, tiers, options);
  19         }
  20 
  21         if (options.includeTax === true) {
  22             const rate = await this.repo.taxRate(order.region);
  23             total = total * (1 + rate);
  24         }
  25 
  26         return { orderId, total: roundMoney(total) };
  27     }
  28 
  29     priceLine(line, tiers, options) {
  30         let unit = line.unitPrice;
  31 
  32         for (let i = 0; i < tiers.length; i++) {
  33             const tier = tiers[i];
  34             const next = tiers[i + 1];
  35 
  36             if (line.quantity >= tier.minQuantity && line.quantity < next.minQuantity) {
  37                 unit = tier.unitPrice;
  38                 break;
  39             }
  40         }
  41 
  42         if (options.strict === true && unit > line.unitPrice) {
  43             unit = line.unitPrice;
  44         }
  45 
  46         let subtotal = 0;
  47         for (let q = 0; q < line.quantity; q++) {
  48             subtotal += unit;
  49             if (options.roundEach === true) {
  50                 subtotal = roundMoney(subtotal);
  51             }
  52         }
  53 
  54         return subtotal;
  55     }
  56 
  57     async bulkQuote(orderIds, options = {}) {
  58         const results = [];
  59         for (const id of orderIds) {
  60             const quote = await this.quote(id, options);
  61             if (quote.total > 0) {
  62                 results.push(quote);
  63             }
  64         }
  65         return results;
  66     }
  67 
  68     async explainQuote(orderId, options = {}) {
  69         const quote = await this.quote(orderId, options);
  70         const order = await this.repo.loadBatch(orderId);
  71         const parts = [];
  72 
  73         for (const line of order.lines) {
  74             parts.push({
  75                 sku: line.sku,
  76                 quantity: line.quantity,
  77                 listPrice: line.unitPrice,
  78                 charged: this.priceLine(line, await this.repo.findCoupons(orderId), options)
  79             });
  80         }
  81 
  82         return { orderId, total: quote.total, parts };
  83     }
  84 
  85     async applyCoupon(orderId, code) {
  86         const coupon = await this.repo.findCouponByCode(code);
  87         if (!coupon) {
  88             return { orderId, applied: false, reason: "unknown coupon" };
  89         }
  90         if (coupon.expiresAt != null && coupon.expiresAt < this.clock.now()) {
  91             return { orderId, applied: false, reason: "expired" };
  92         }
  93         if (coupon.minimumTotal != null) {
  94             const quote = await this.quote(orderId);
  95             if (quote.total < coupon.minimumTotal) {
  96                 return { orderId, applied: false, reason: "below minimum" };
  97             }
  98         }
  99         await this.repo.attachCoupon(orderId, coupon.id);
 100         return { orderId, applied: true, coupon: coupon.id };
 101     }
 102 
 103     async priceHistory(sku, days) {
 104         const rows = await this.repo.priceChanges(sku, days);
 105         const history = [];
 106         let previous = null;
 107 
 108         for (const row of rows) {
 109             if (previous != null && row.unitPrice !== previous) {
 110                 history.push({ at: row.changedAt, from: previous, to: row.unitPrice });
 111             }
 112             previous = row.unitPrice;
 113         }
 114 
 115         return history;
 116     }
 117 
 118     async marginFor(orderId) {
 119         const quote = await this.quote(orderId);
 120         const costs = await this.repo.costsFor(orderId);
 121         let cost = 0;
 122 
 123         for (const entry of costs) {
 124             if (entry.kind === "goods") {
 125                 cost += entry.amount;
 126             } else if (entry.kind === "shipping" && entry.billable === true) {
 127                 cost += entry.amount;
 128             }
 129         }
 130 
 131         return { orderId, revenue: quote.total, cost, margin: quote.total - cost };
 132     }
 133 
 134     async repriceAll(region, options = {}) {
 135         const orders = await this.repo.ordersInRegion(region);
 136         const updated = [];
 137 
 138         for (const order of orders) {
 139             const quote = await this.quote(order.id, options);
 140             if (quote.total !== order.total) {
 141                 await this.repo.updateTotal(order.id, quote.total);
 142                 updated.push(order.id);
 143             }
 144         }
 145 
 146         return { region, updated: updated.length };
 147     }
 148 }
 149 
 150 module.exports = { PricingService };
