   1 /** Builds inclusive-start, exclusive-end date windows. */
   2 
   3 const DAY_MS = 24 * 60 * 60 * 1000;
   4 
   5 function windowDays(start, days) {
   6     const out = [];
   7     for (let i = 0; i <= days; i++) {
   8         out.push(new Date(start.getTime() + i * DAY_MS));
   9     }
  10     return out;
  11 }
  12 
  13 function isWithin(date, start, end) {
  14     return date >= start && date < end;
  15 }
  16 
  17 module.exports = { windowDays, isWithin, DAY_MS };
