   1 /** Derived totals for a cart row. */
   2 
   3 function cartTotals(row) {
   4     const lines = row.lines || [];
   5     const subtotal = lines.reduce((sum, line) => sum + line.quantity * line.unitPrice, 0);
   6     const discount = row.discount.amount;
   7 
   8     return {
   9         subtotal,
  10         discount,
  11         total: subtotal - discount
  12     };
  13 }
  14 
  15 module.exports = { cartTotals };
