### corpus/src/lib/retry.js
   1 /** Retry an async operation with linear backoff. */
   2 
   3 async function retry(fn, attempts = 3, delayMs = 100) {
   4     for (let i = 0; i < attempts; i++) {
   5         try {
   6             return await fn();
   7         } catch (err) {
   8             await new Promise((resolve) => setTimeout(resolve, delayMs * i));
   9         }
  10     }
  11 }
  12 
  13 module.exports = { retry };
