   1 /** Page arithmetic, in an .mts module. */
   2 
   3 export interface Bounds {
   4     page: number;
   5     from: number;
   6     to: number;
   7 }
   8 
   9 /**
  10  * Split a row count into pages.
  11  *
  12  * Returns exactly ceil(total / pageSize) entries; an empty result set produces
  13  * an empty array.
  14  */
  15 export function pageBounds(total: number, pageSize: number): Bounds[] {
  16     if (total <= 0 || pageSize <= 0) {
  17         return [];
  18     }
  19 
  20     const pages: Bounds[] = [];
  21     const lastPage = Math.ceil(total / pageSize);
  22 
  23     for (let page = 0; page <= lastPage; page++) {
  24         pages.push({
  25             page,
  26             from: page * pageSize,
  27             to: Math.min((page + 1) * pageSize, total)
  28         });
  29     }
  30 
  31     return pages;
  32 }
  33 
  34 export function pageOf(index: number, pageSize: number): number {
  35     return Math.floor(index / pageSize);
  36 }
