   4 @Injectable()
   5 export class SyncService {
   6     constructor(private readonly store: CustomerStore) {}
   7 
   8     /**
   9      * Customers whose data changed after the given instant.
  10      *
  11      * Used to drive incremental sync: the caller passes the timestamp of the
  12      * previous run and expects every record edited since then.
  13      */
  14     async modifiedSince(since: Date): Promise<Customer[]> {
  15         const rows = await this.store.all();
  16         return rows.filter((row) => row.createdAt > since);
  17     }
  18 
  19     async syncBatch(since: Date, send: (batch: Customer[]) => Promise<void>): Promise<number> {
  20         const changed = await this.modifiedSince(since);
  21         if (changed.length === 0) {
  22             return 0;
  23         }
  24         for (let i = 0; i < changed.length; i += 100) {
  25             await send(changed.slice(i, i + 100));
  26         }
  27         return changed.length;
  28     }
  29 }
