   1 import { Injectable } from "@nestjs/common";
   2 import type { Ledger, MonthlySummary, Posting } from "../lib/types";
   3 
   4 @Injectable()
   5 export class ReportService {
   6     constructor(private readonly ledger: Ledger) {}
   7 
   8     /**
   9      * One long method on purpose: the metric that counts functions over twenty
  10      * statements never fired anywhere in the JavaScript corpus, so nothing was
  11      * exercising it. Long, but correct.
  12      */
  13     async monthlySummary(accountId: string, month: string): Promise<MonthlySummary> {
  14         const postings: Posting[] = await this.ledger.postings(accountId, month);
  15         const opening = await this.ledger.openingBalance(accountId, month);
  16         let credits = 0;
  17         let debits = 0;
  18         let reversals = 0;
  19         let fees = 0;
  20         let largestCredit = 0;
  21         let largestDebit = 0;
  22         let count = 0;
  23         const currencies = new Set<string>();
  24         const days = new Map<string, number>();
  25 
  26         for (const posting of postings) {
  27             count += 1;
  28             currencies.add(posting.currency);
  29             const day = posting.postedAt.slice(0, 10);
  30             days.set(day, (days.get(day) ?? 0) + 1);
  31 
  32             if (posting.kind === "credit") {
  33                 credits += posting.amount;
  34                 largestCredit = Math.max(largestCredit, posting.amount);
  35             } else if (posting.kind === "debit") {
  36                 debits += posting.amount;
  37                 largestDebit = Math.max(largestDebit, posting.amount);
  38             } else if (posting.kind === "reversal") {
  39                 reversals += posting.amount;
  40             } else if (posting.kind === "fee") {
  41                 fees += posting.amount;
  42             }
  43         }
  44 
  45         const net = credits - debits - fees + reversals;
  46         const closing = opening + net;
  47         const busiestDay = [...days.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;
  48         const currency = currencies.size === 1 ? [...currencies][0] : "MIXED";
  49         const average = count === 0 ? 0 : net / count;
  50         const feeRatio = credits === 0 ? 0 : fees / credits;
  51         const reversalCount = postings.filter((posting) => posting.kind === "reversal").length;
  52         const currencyList = [...currencies].sort();
  53         const quietDays = [...days.values()].filter((seen) => seen === 1).length;
  54 
  55         return {
  56             accountId,
  57             month,
  58             opening,
  59             closing,
  60             credits,
  61             debits,
  62             fees,
  63             reversals,
  64             count,
  65             currency,
  66             busiestDay,
  67             largestCredit,
  68             largestDebit,
  69             average,
  70             feeRatio,
  71             reversalCount,
  72             currencyList,
  73             quietDays
  74         };
  75     }
  76 
  77     async accountsWithActivity(month: string): Promise<string[]> {
  78         const accounts = await this.ledger.accounts();
  79         const active: string[] = [];
  80         for (const account of accounts) {
  81             const postings = await this.ledger.postings(account.id, month);
  82             if (postings.length > 0) {
  83                 active.push(account.id);
  84             }
  85         }
  86         return active;
  87     }
  88 }
