  18 export function add(a: Money, b: Money): Money {
  19     if (a.currency !== b.currency) {
  20         throw new Error(`cannot add ${a.currency} to ${b.currency}`);
  21     }
  22     return { amount: roundMoney(a.amount + b.amount), currency: a.currency };
