 134     async repriceAll(region, options = {}) {
 135         const orders = await this.repo.ordersInRegion(region);
 136         const updated = [];
 137 
 138         for (const order of orders) {
 139             const quote = await this.quote(order.id, options);
 140             if (quote.total !== order.total) {
 141                 await this.repo.updateTotal(order.id, quote.total);
 142                 updated.push(order.id);
 143             }
 144         }
 145 
 146         return { region, updated: updated.length };
 147     }
