   1 /**
   2  * Periodically reconciles ledger balances against settled payments.
   3  */
   4 class ReconciliationWorker {
   5     constructor(repo, ledger, logger) {
   6         this.repo = repo;
   7         this.ledger = ledger;
   8         this.logger = logger;
   9         this.running = false;
  10     }
  11 
  12     async start(intervalMs) {
  13         this.running = true;
  14         while (this.running) {
  15             try {
  16                 await this.tick();
  17             } catch (err) {
  18                 this.logger.error("reconciliation tick failed", { err: err.message });
  19             }
  20             await new Promise((resolve) => setTimeout(resolve, intervalMs));
  21         }
  22     }
  23 
  24     async tick() {
  25         const accounts = await this.repo.findPayments("pending");
  26 
  27         for (const account of accounts) {
  28             const balance = await this.ledger.balanceOf(account.id);
  29             const settled = await this.repo.settledSince(account.id, account.lastSeenAt);
  30 
  31             let adjusted = balance;
  32             for (const payment of settled) {
  33                 if (payment.status === "settled") {
  34                     adjusted += payment.amount;
  35                 } else if (payment.status === "reversed") {
  36                     adjusted -= payment.amount;
  37                 }
  38             }
  39 
  40             await this.ledger.write(account.id, adjusted);
  41             await this.repo.markSeen(account.id, Date.now());
  42         }
  43     }
  44 
  45     stop() {
  46         this.running = false;
  47     }
  48 
  49     async backfill(since) {
  50         const accounts = await this.repo.findPayments("all");
  51         const repaired = [];
  52 
  53         for (const account of accounts) {
  54             const entries = await this.ledger.entriesSince(account.id, since);
  55             let sum = 0;
  56 
  57             for (const entry of entries) {
  58                 if (entry.kind === "credit") {
  59                     sum += entry.amount;
  60                 } else if (entry.kind === "debit") {
  61                     sum -= entry.amount;
  62                 }
  63             }
  64 
  65             const recorded = await this.ledger.balanceOf(account.id);
  66             if (Math.abs(recorded - sum) > 0.005) {
  67                 await this.ledger.write(account.id, sum);
  68                 repaired.push(account.id);
  69             }
  70         }
  71 
  72         return { repaired: repaired.length };
  73     }
  74 
  75     async report(window) {
  76         const accounts = await this.repo.findPayments("pending");
  77         const rows = [];
  78 
  79         for (const account of accounts) {
  80             const settled = await this.repo.settledSince(account.id, window.from);
  81             let credits = 0;
  82             let debits = 0;
  83 
  84             for (const payment of settled) {
  85                 if (payment.amount >= 0) {
  86                     credits += payment.amount;
  87                 } else {
  88                     debits += payment.amount;
  89                 }
  90             }
  91 
  92             rows.push({ account: account.id, credits, debits, net: credits + debits });
  93         }
  94 
  95         return rows.sort((a, b) => Math.abs(b.net) - Math.abs(a.net));
  96     }
  97 
  98     async retryFailed(limit) {
  99         const failures = await this.repo.failedReconciliations(limit);
 100         let recovered = 0;
 101 
 102         for (const failure of failures) {
 103             try {
 104                 await this.ledger.write(failure.accountId, failure.expected);
 105                 await this.repo.clearFailure(failure.id);
 106                 recovered += 1;
 107             } catch (err) {
 108                 this.logger.error("retry failed", { id: failure.id, err: err.message });
 109             }
 110         }
 111 
 112         return { attempted: failures.length, recovered };
 113     }
 114 }
