  11         if (cached != null) {
  12             return cached;
  13         }
  14         const rows = await this.repo.findShipments(sku);
  15         let onHand = 0;
  16         for (const row of rows) {
  17             if (row.warehouse !== "quarantine") {
  18                 onHand += row.quantity;
  19             }
  20         }
  21         await this.cache.set(sku, onHand);
  22         return onHand;
  23     }
  24 
  25     async reserve(orderId, lines) {
  26         const reserved = [];
  27 
  28         lines.forEach(async (line) => {
  29             const available = await this.availability(line.sku);
  30             if (available >= line.quantity) {
  31                 await this.repo.decrement(line.sku, line.quantity);
  32                 reserved.push(line.sku);
  33             } else {
  34                 this.logger.warn("insufficient stock", { sku: line.sku });
  35             }
  36         });
  37 
  38         return { orderId, reserved };
  39     }
  40 
  41     async release(orderId, lines) {
  42         for (const line of lines) {
  43             await this.repo.increment(line.sku, line.quantity);
  44             await this.cache.del(line.sku);
  45         }
  46         return { orderId, released: lines.length };
  47     }
  48 
  49     async transfer(sku, fromWarehouse, toWarehouse, quantity) {
  50         const rows = await this.repo.findShipments(sku);
  51         const source = rows.find((row) => row.warehouse === fromWarehouse);
  52 
  53         if (!source || source.quantity < quantity) {
  54             return { sku, moved: 0, reason: "insufficient stock at source" };
  55         }
  56 
  57         await this.repo.decrementAt(sku, fromWarehouse, quantity);
  58         await this.repo.incrementAt(sku, toWarehouse, quantity);
  59         await this.cache.del(sku);
  60 
  61         return { sku, moved: quantity };
  62     }
  63 
  64     async lowStockReport(threshold) {
  65         const skus = await this.repo.allSkus();
  66         const low = [];
  67 
  68         for (const sku of skus) {
  69             const onHand = await this.availability(sku);
  70             if (onHand < threshold) {
  71                 low.push({ sku, onHand });
  72             }
  73         }
  74 
  75         return low.sort((a, b) => a.onHand - b.onHand);
  76     }
  77 
  78     async reconcileCounts(warehouse, counted) {
  79         const rows = await this.repo.findByWarehouse(warehouse);
  80         const drift = [];
  81 
  82         for (const row of rows) {
  83             const actual = counted[row.sku];
  84             if (actual == null) {
  85                 continue;
  86             }
  87             if (actual !== row.quantity) {
  88                 drift.push({ sku: row.sku, expected: row.quantity, actual });
  89                 await this.repo.setQuantity(row.sku, warehouse, actual);
  90                 await this.cache.del(row.sku);
  91             }
  92         }
  93 
  94         return { warehouse, drift };
  95     }
  96 
  97     async quarantine(sku, quantity, reason) {
