   1 import { Injectable, OnModuleDestroy } from "@nestjs/common";
   2 import type { Clock } from "../lib/types";
   3 
   4 interface CacheEntry {
   5     value: unknown;
   6     expiresAt: number;
   7 }
   8 
   9 /**
  10  * In-memory cache with a background sweep.
  11  *
  12  * Implements OnModuleDestroy so the container can release what this holds.
  13  */
  14 @Injectable()
  15 export class CacheService implements OnModuleDestroy {
  16     private readonly entries = new Map<string, CacheEntry>();
  17     private readonly sweep: NodeJS.Timeout;
  18 
  19     constructor(private readonly clock: Clock) {
  20         this.sweep = setInterval(() => this.evictExpired(), 60_000);
  21     }
  22 
  23     onModuleDestroy(): void {
  24         this.entries.clear();
  25     }
  26 
  27     get<T>(key: string): T | null {
  28         const entry = this.entries.get(key);
  29         if (!entry) {
  30             return null;
  31         }
  32         if (entry.expiresAt <= this.clock.now()) {
  33             this.entries.delete(key);
  34             return null;
  35         }
  36         return entry.value as T;
  37     }
  38 
  39     set(key: string, value: unknown, ttlMs: number): void {
  40         this.entries.set(key, { value, expiresAt: this.clock.now() + ttlMs });
  41     }
  42 
  43     delete(key: string): void {
  44         this.entries.delete(key);
  45     }
  46 
  47     private evictExpired(): void {
  48         const now = this.clock.now();
  49         for (const [key, entry] of this.entries) {
  50             if (entry.expiresAt <= now) {
  51                 this.entries.delete(key);
  52             }
  53         }
  54     }
  55 
  56     size(): number {
  57         return this.entries.size;
  58     }
  59 }
